  const old=audio;silence();audio=null;
  if(old&&old.state!=='closed')try{void old.close().catch(()=>{})}catch{}
  audio=new(window.AudioContext||window.webkitAudioContext)();audioNeedsReset=false;
  const context=audio;
  context.addEventListener('statechange',()=>{if(audio===context&&['interrupted','closed'].includes(context.state))audioNeedsReset=true});
